#!/usr/bin/env bash
# Baja los originales full-res de Wix a assets/img/. Corre esto UNA vez en tu Mac,
# parado en la carpeta 'site'. Requiere curl (ya viene en macOS).
set -u
cd "$(dirname "$0")" || exit 1

dl () {
  local url="$1" dest="$2"
  mkdir -p "$(dirname "$dest")"
  if [ -s "$dest" ]; then echo "  ya existe: $dest"; return; fi
  echo "bajando: $dest"
  curl -fsSL "$url" -o "$dest" || echo "  !! fallo: $url"
}

